Literal.Value:
'.ty { position: relative; width: 100%; height: 100vh; min-height: 700px; overflow: hidden; background: #F4F9F8; font-family: ''Segoe UI'', wf_segoe-ui_normal, helvetica, arial, sans-serif; color: #0B1A17; }
.ty-bar { position: absolute; left: 0; top: 0; width: 1280px; height: 5px; background: #116B62; z-index: 2; }
.ty-side { position: absolute; left: 0; top: 0; width: 399px; height: 720px; background: #FFFFFF; border-right: 1px solid #CFE3DD; text-align: center; }
.ty-logo { position: absolute; left: 145px; top: 52px; width: 110px; height: 110px; }
.ty-brand { position: absolute; left: 0; width: 400px; top: 178px; font-size: 22px; font-weight: 700; color: #116B62; line-height: 28px; }
.ty-photo { position: absolute; left: 134px; top: 238px; width: 132px; height: 97px; border-radius: 6px; object-fit: contain; }
.ty-badge { position: absolute; left: 152px; top: 364px; width: 96px; height: 99px; object-fit: contain; }
.ty-name { position: absolute; left: 0; width: 400px; top: 500px; font-size: 17px; font-weight: 700; line-height: 24px; }
.ty-skills { position: absolute; left: 0; width: 400px; top: 527px; font-size: 11.5px; color: #44544F; line-height: 18px; }
.ty-rule { position: absolute; left: 160px; top: 560px; width: 80px; height: 1px; background: #3FB8A6; }
.ty-small { position: relative; top: 579px; font-size: 10.5px; line-height: 18px; color: #44544F; opacity: .85; }
.ty-site { position: absolute; left: 0; width: 400px; top: 643px; font-size: 12px; font-weight: 700; color: #116B62; line-height: 18px; }
.ty-main { position: absolute; left: 440px; top: 0; width: 760px; height: 720px; }
.ty-stamp { position: absolute; right: 0; top: 30px; font-size: 11px; color: #116B62; background: #E3F0EC; border-radius: 10px; padding: 2px 10px; line-height: 16px; }
.ty-stamp:empty { display: none; }
.ty-headline { position: absolute; left: 0; top: 80px; margin: 0; font-size: 36px; font-weight: 700; line-height: 48px; }
.ty-tagline { position: absolute; left: 0; top: 132px; font-size: 13.5px; color: #44544F; line-height: 20px; }
.ty-accent { position: absolute; left: 0; top: 164px; width: 56px; height: 2px; background: #116B62; }
.ty-link { position: relative; display: flex; align-items: center; box-sizing: border-box; width: 760px; height: 68px; margin-top: 24px; padding: 0 20px 0 24px; background: #FFFFFF; border: 1px solid #CFE3DD; border-radius: 8px; text-decoration: none; color: #0B1A17; cursor: pointer; }
.ty-link:first-of-type { margin-top: 196px; }
.ty-link:hover { border-color: #116B62; box-shadow: 0 2px 8px rgba(17, 107, 98, .15); }
.ty-glyph { flex: 0 0 36px; height: 36px; border-radius: 9px; background: #D5E4DF; color: #116B62; font-size: 16px; font-weight: 700; line-height: 36px; text-align: center; }
.ty-text { flex: 1; display: flex; flex-direction: column; margin-left: 20px; }
.ty-label { font-size: 16px; font-weight: 700; line-height: 20px; }
.ty-url { font-family: Consolas, monospace; font-size: 11px; color: #44544F; line-height: 16px; margin-top: 2px; }
.ty-arrow { font-size: 22px; color: #116B62; }
.ty-link.primary { background: #116B62; border-color: #116B62; color: #FFFFFF; }
.ty-link.primary .ty-glyph { background: #3FB8A6; color: #0B1A17; }
.ty-link.primary .ty-url { color: #C9E7E1; }
.ty-link.primary .ty-arrow { color: #FFFFFF; }
.ty-author { position: absolute; right: 0; top: 684px; font-size: 10px; color: #44544F; opacity: .7; line-height: 16px; }'
